73	@RestController
74	@CrossOrigin(exposedHeaders = "errors, content-type")
75	@RequestMapping("/api")
76	public class OwnerRestControllerV1 implements OwnersApi {
77	
78	    /** Maximum number of owners a single city may contain; creating an owner in a city that
79	     *  already has this many owners is rejected with 409 Conflict. */
80	    private static final int MAX_OWNERS_PER_CITY = 50;
81	
82	    /** Maximum number of owners that may be created on a single day (by registration date); creating
83	     *  an owner once this many owners already carry today's registration date is rejected with
84	     *  429 Too Many Requests. */
85	    private static final int MAX_OWNERS_PER_DAY = 100;
86	
87	    /** When more than this many owners already carry today's registration date at creation time, the
88	     *  new owner's 'bulkSignupWarning' flag is set true; otherwise it is false. */
89	    private static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
90	
91	    /** Disposable email domains that are not accepted for an owner; a create whose email domain is on
92	     *  this blocklist is rejected with 400 Bad Request. Compared case-insensitively (lower-cased). */
93	    private static final Set<String> DISPOSABLE_EMAIL_DOMAINS =
94	        Set.of("mailinator.com", "tempmail.com", "guerrillamail.com");
95	
96	    /** Dedicated audit logger; a line is emitted here for each successful owner create. */
97	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
98	
99	    private final ClinicService clinicService;
100	
101	    private final OwnerMapper ownerMapper;
102	
103	    private final PetMapper petMapper;
104	
105	    private final VisitMapper visitMapper;
106	
107	    private final TelephoneNormalizer telephoneNormalizer;
108	
109	    private final HouseholdNormalizer householdNormalizer;
110	
111	    private final AddressNormalizer addressNormalizer;
112	
113	    private final EmailNormalizer emailNormalizer;
114	
115	    /**
116	     * Records the owner created for each already-seen {@code Idempotency-Key}, so a create that
117	     * repeats with the same key returns the originally created owner (200) instead of creating a
118	     * duplicate. Keyed by the header value; concurrent because creates may be handled on any thread.
119	     */
120	    private final java.util.concurrent.ConcurrentMap<String, OwnerDto> idempotentCreates =
121	        new java.util.concurrent.ConcurrentHashMap<>();
122	
123	    public OwnerRestControllerV1(ClinicService clinicService,
124	                                 OwnerMapper ownerMapper,
125	                                 PetMapper petMapper,
126	                                 VisitMapper visitMapper,
127	                                 TelephoneNormalizer telephoneNormalizer,
128	                                 HouseholdNormalizer householdNormalizer,
129	                                 AddressNormalizer addressNormalizer,
130	                                 EmailNormalizer emailNormalizer) {
131	        this.clinicService = clinicService;
132	        this.ownerMapper = ownerMapper;
133	        this.petMapper = petMapper;
134	        this.visitMapper = visitMapper;
135	        this.telephoneNormalizer = telephoneNormalizer;
136	        this.householdNormalizer = householdNormalizer;
137	        this.addressNormalizer = addressNormalizer;
138	        this.emailNormalizer = emailNormalizer;
139	    }
140	
141	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
142	    @Override
143	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
144	        Collection<Owner> owners;
145	        if (lastName != null) {
146	            owners = this.clinicService.findOwnerByLastName(lastName);
147	        } else {
148	            owners = this.clinicService.findAllOwners();
149	        }
150	        if (owners.isEmpty()) {
151	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
152	        }
153	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
154	    }
155	
156	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
157	    @Override
158	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
159	        Owner owner = this.clinicService.findOwnerById(ownerId);
160	        if (owner == null) {
161	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
162	        }
163	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
164	    }
165	
166	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
167	    @Override
168	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
169	        // Idempotent create: when the request carries an 'Idempotency-Key' header that has already
170	        // been used for a successful create, return the originally created owner with 200 OK instead
171	        // of running the create pipeline again (which would otherwise reject the repeat as a duplicate
172	        // with 409). A first, unseen key runs the normal create and records its result under the key.
173	        String idempotencyKey = currentIdempotencyKey();
174	        if (idempotencyKey == null || idempotencyKey.isBlank()) {
175	            return createOwner(ownerFieldsDto);
176	        }
177	        OwnerDto previouslyCreated = idempotentCreates.get(idempotencyKey);
178	        if (previouslyCreated != null) {
179	            return new ResponseEntity<>(previouslyCreated, HttpStatus.OK);
180	        }
181	        ResponseEntity<OwnerDto> response = createOwner(ownerFieldsDto);
182	        idempotentCreates.put(idempotencyKey, response.getBody());
183	        return response;
184	    }
185	
186	    /**
187	     * Returns the value of the current request's {@code Idempotency-Key} header, or {@code null} when
188	     * the request carries no such header (or there is no active servlet request). Reading it from the
189	     * request context here keeps the header — a request-level concern surrounding the create — out of
190	     * the generated {@link #addOwner} signature and the {@link #createOwner} pipeline.
191	     *
192	     * @return the {@code Idempotency-Key} header value, or {@code null} when absent
193	     */
194	    private String currentIdempotencyKey() {
195	        RequestAttributes attributes = RequestContextHolder.getRequestAttributes();
196	        if (attributes instanceof ServletRequestAttributes servletAttributes) {
197	            return servletAttributes.getRequest().getHeader("Idempotency-Key");
198	        }
199	        return null;
200	    }
201	
202	    /**
203	     * Runs the full owner-creation pipeline for a create request and returns the 201 Created
204	     * response for the newly persisted owner: the request fields are mapped and normalized, every
205	     * create-time policy (per-day and per-city quota, household membership, identity duplicate and
206	     * soft-duplicate) is applied in order, the create-time derived fields are assigned, the owner is
207	     * saved and audited, and a {@code Location} header for the new owner is set. Keeping the pipeline
208	     * in its own method leaves {@link #addOwner} as the thin request entry point, so request-level
209	     * concerns that merely surround a create (rather than being one of its steps) can be layered in
210	     * {@code addOwner} without disturbing the creation steps gathered here.
211	     *
212	     * @param ownerFieldsDto the submitted owner fields
213	     * @return a 201 Created response carrying the persisted owner and its {@code Location} header
214	     */
215	    private ResponseEntity<OwnerDto> createOwner(OwnerFieldsDto ownerFieldsDto) {
216	        HttpHeaders headers = new HttpHeaders();
217	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
218	        normalizeOwnerFields(owner);
219	        // Enforce the pre-persistence policies that can reject the new owner outright.
220	        rejectDisallowedOwnerCreation(owner);
221	        // Resolve the owner's household membership: assign the deterministic 'householdId' (a pure
222	        // function of last name and postcode), reject a household duplicate unless the request
223	        // declares it shares the household, and record the household size. This runs before the
224	        // identity-key check so that check sees the owner's household id.
225	        boolean declaredHouseholdMember =
226	            applyHouseholdMembership(owner, Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold()));
227	        // Reject the create when the owner's whole derived identity key (normalized telephone,
228	        // email and household id) already matches an existing owner. This single rule subsumes the
229	        // former separate telephone, email and household duplicate checks.
230	        rejectWhenIdentityInUse(owner);
231	        // Flag the owner as a possible (soft) duplicate when, although not a hard duplicate, it
232	        // shares an existing owner's last name and postcode with a different telephone. A declared
233	        // household member is never flagged: it is a known member, not a suspected duplicate.
234	        assignPossibleDuplicate(owner, declaredHouseholdMember);
235	        // Assign the remaining create-time derived fields (namesake count, customer code,
236	        // membership number and bulk-signup warning), each fixed at creation time.
237	        assignDerivedFields(owner);
238	        this.clinicService.saveOwner(owner);
239	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
240	        // Emit an audit line for the successful create, carrying the owner id, customer code,
241	        // registration date, membership level and membership number so the create can be traced
242	        // from the dedicated AUDIT log.
243	        AUDIT.info("Owner created: id={} customerCode={} registrationDate={} membershipLevel={} membershipNumber={}",
244	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
245	            ownerDto.getMembershipLevel(), ownerDto.getMembershipNumber());
246	        headers.setLocation(UriComponentsBuilder.newInstance()
247	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
248	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
249	    }
250	
251	    /**
252	     * Enforces the pre-persistence policies that reject a newly mapped and normalized owner
253	     * outright, in order, before any derived fields are assigned or the owner is saved. Each
254	     * independent rule lives in its own {@code rejectWhen...} guard and is applied here in order, so
255	     * the sequence of create-time rejections stays readable and a new rule is added as one more
256	     * guard. Grouping the rules here keeps {@link #addOwner} focused on the household, derived-field
257	     * and persistence steps. The single duplicate rule that rejects an owner whose whole identity
258	     * key matches an existing one is applied separately in {@link #rejectWhenIdentityInUse}, after
259	     * the household id has been resolved, because that key includes the household id.
260	     *
261	     * @param owner the newly mapped and normalized owner being created
262	     */
263	    private void rejectDisallowedOwnerCreation(Owner owner) {
264	        rejectWhenDailyLimitReached(owner);
265	        rejectWhenCityAtCapacity(owner);
266	    }
267	
268	    /**
269	     * Applies the household-membership rules for a newly normalized owner being created. The
270	     * household id is a deterministic function of the owner's last name and postcode, so owners
271	     * with the same last name and postcode share it automatically; it is assigned to the new owner
272	     * here. Because the household is keyed on (last name, postcode), any existing owner with the
273	     * same last name and postcode is a member of the same household: a second such owner is rejected
274	     * as a household duplicate (409) unless the request declares it shares the household via
275	     * {@code sharesHousehold}, in which case it is created as a declared household member. The
276	     * owner's {@code householdSize} (the number of owners sharing the household after this create)
277	     * is recorded either way. The assigned household id is part of the owner's identity key, so it
278	     * is resolved here before {@link #rejectWhenIdentityInUse}.
279	     *
280	     * @param owner           the newly mapped and normalized owner being created
281	     * @param sharesHousehold whether the request declared that the owner shares an existing household
282	     * @return {@code true} if the owner joined an existing household as a declared member
283	     */
284	    private boolean applyHouseholdMembership(Owner owner, boolean sharesHousehold) {
285	        // Assign the deterministic household id (a pure function of last name and postcode) so every
286	        // owner with the same last name and postcode shares it automatically.
287	        owner.setHouseholdId(householdNormalizer.householdId(owner.getLastName(), owner.getPostcode()));
288	        // Identify any existing owners in the same household (same computed household id).
289	        List<Owner> householdMembers = sameHouseholdOwners(owner);
290	        // A second owner in an existing household is a household duplicate: reject it with 409 unless
291	        // the request declares it shares the household, in which case create it as a declared member.
292	        boolean declaredHouseholdMember = false;
293	        if (!householdMembers.isEmpty()) {
294	            if (!sharesHousehold) {
295	                throw new HouseholdDuplicateException(
296	                    "An owner in the household " + owner.getHouseholdId() + " already exists");
297	            }
298	            declaredHouseholdMember = true;
299	        }
300	        // Record the size of this owner's household after this create, fixed at creation time.
301	        owner.setHouseholdSize(householdMembers.size() + 1);
302	        return declaredHouseholdMember;
303	    }
304	
305	    /**
306	     * Assigns the create-time derived fields of a newly normalized owner whose household membership
307	     * has already been resolved: the namesake count, the per-city customer code, the membership
308	     * number derived from that customer code and the registration fiscal year, and the bulk-signup warning
309	     * flag. Each value is fixed at creation time and is independent of the others. Grouping them
310	     * here keeps {@link #addOwner} focused on the high-level create sequence.
311	     *
312	     * @param owner the owner being created, already normalized and with its household resolved
313	     */
314	    private void assignDerivedFields(Owner owner) {
315	        // Record how many existing owners already share this owner's first and last name
316	        // (compared case-insensitively) before this create, fixed at creation time.
317	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
318	        // Assign the customer code '<REGION>-<HASH8>' from the region derived from the postcode
319	        // and an 8-hex-character hash of the normalized telephone and last name, fixed at creation
320	        // time.
321	        owner.setCustomerCode(customerCode(owner));
322	        // Assign the membership number '<customerCode>-M<YY>', where YY is the last two digits
323	        // of the fiscal year of the registration date (e.g. 'NSW-A1B2C3D4-M26'), fixed at
324	        // creation time.
325	        owner.setMembershipNumber(membershipNumber(owner.getCustomerCode(), owner.getRegistrationDate()));
326	        // Flag the create when more than 80 owners have already been created on this owner's
327	        // (adjusted business-day) registration date, fixed at creation time.
328	        owner.setBulkSignupWarning(
329	            countOwnersRegisteredOn(owner.getRegistrationDate()) > BULK_SIGNUP_WARNING_THRESHOLD);
330	    }
331	
332	    /**
333	     * Rejects creating an owner whose whole derived identity key already matches an existing owner,
334	     * with 409 Conflict. The identity key ({@link Owner#getIdentityKey()}) joins the normalized
335	     * telephone, the email (or empty) and the household id (or empty), so this single rule replaces
336	     * the former separate telephone, email and household duplicate checks: two owners collide only
337	     * when their whole keys are equal, and members of one household with different telephones have
338	     * different keys and are both allowed.
339	     *
340	     * @param owner the owner being created, already normalized and with its household resolved
341	     */
342	    private void rejectWhenIdentityInUse(Owner owner) {
343	        String identityKey = owner.getIdentityKey();
344	        boolean inUse = existingOwners()
345	            .anyMatch(existing -> identityKey.equals(existing.getIdentityKey()));
346	        if (inUse) {
347	            throw new DuplicateIdentityException(
348	                "An owner with identity key " + identityKey + " already exists");
349	        }
350	    }
351	
352	    /**
353	     * Assigns the soft-duplicate flags for a newly normalized owner that has already passed the hard
354	     * duplicate (identity-key) check. When an existing owner shares this owner's last name (compared
355	     * case-insensitively) and postcode but carries a different (normalized) telephone, the new owner
356	     * is still created but flagged as a possible duplicate: {@code possibleDuplicate} is set true and
357	     * {@code possibleDuplicateOf} to the matching owner's id (the lowest such id when several match).
358	     * Otherwise {@code possibleDuplicate} is false and {@code possibleDuplicateOf} is left absent.
359	     * A postcode is required on both sides for a match, so an owner without a postcode is never a
360	     * possible duplicate. A declared household member is never flagged: it is a known member of the
361	     * household, not a suspected duplicate. Both values are fixed at creation time.
362	     *
363	     * @param owner                   the owner being created, already normalized and confirmed not a
364	     *                                hard duplicate
365	     * @param declaredHouseholdMember whether the owner joined an existing household as a declared
366	     *                                member
367	     */
368	    private void assignPossibleDuplicate(Owner owner, boolean declaredHouseholdMember) {
369	        Integer matchId = declaredHouseholdMember || owner.getPostcode() == null ? null : existingOwners()
370	            .filter(existing -> isPossibleDuplicateOf(existing, owner))
371	            .map(Owner::getId)
372	            .min(Integer::compareTo)
373	            .orElse(null);
374	        owner.setPossibleDuplicate(matchId != null);
375	        owner.setPossibleDuplicateOf(matchId);
376	    }
377	
378	    /**
379	     * Tests whether an existing owner makes the owner being created a possible (soft) duplicate: the
380	     * two share a postcode (required on both sides, so an owner without a postcode never matches) and
381	     * a last name (compared case-insensitively) but carry different (normalized) telephones. A match
382	     * flags the new owner as a possible duplicate of the existing one without rejecting the create.
383	     *
384	     * @param existing an existing owner to compare against
385	     * @param owner    the owner being created
386	     * @return {@code true} if the existing owner makes the new owner a possible duplicate
387	     */
388	    private boolean isPossibleDuplicateOf(Owner existing, Owner owner) {
389	        return existing.getPostcode() != null
390	            && existing.getPostcode().equals(owner.getPostcode())
391	            && existing.getLastName() != null
392	            && existing.getLastName().equalsIgnoreCase(owner.getLastName())
393	            && existing.getTelephone() != null
394	            && !existing.getTelephone().equals(owner.getTelephone());
395	    }
396	
397	    /**
398	     * Rejects creating an owner once {@link #MAX_OWNERS_PER_DAY} or more owners already carry this
399	     * owner's adjusted business-day registration date, with 429 Too Many Requests.
400	     *
401	     * @param owner the owner being created
402	     */
403	    private void rejectWhenDailyLimitReached(Owner owner) {
404	        if (countOwnersRegisteredOn(owner.getRegistrationDate()) >= MAX_OWNERS_PER_DAY) {
405	            throw new DailyOwnerLimitExceededException(
406	                "The maximum number of owners that may be created today has already been reached");
407	        }
408	    }
409	
410	    /**
411	     * Rejects creating an owner when the owner's city already contains {@link #MAX_OWNERS_PER_CITY}
412	     * or more owners, with 409 Conflict.
413	     *
414	     * @param owner the owner being created
415	     */
416	    private void rejectWhenCityAtCapacity(Owner owner) {
417	        if (countOwnersInCity(owner.getCity()) >= MAX_OWNERS_PER_CITY) {
418	            throw new CityCapacityExceededException(
419	                "The city " + owner.getCity() + " already contains the maximum number of owners");
420	        }
421	    }
422	
423	    /**
424	     * Canonicalizes the fields of a newly mapped owner on create, in place, so each value is
425	     * persisted and returned in its canonical form. The address is normalized (trimmed, whitespace
426	     * collapsed, upper-cased and common abbreviations expanded, rejecting a value blank after
427	     * normalization with 400), the telephone is normalized to E.164 (rejecting an unformattable
428	     * value with 400), the email is lower-cased, and a missing registration date defaults to the
429	     * server's current date. Canonicalising the address here, before the household checks read it,
430	     * ensures duplicate detection and the shared household id both compare the normalized form.
431	     * Centralising these per-field canonicalizations here keeps {@link #addOwner} focused on the
432	     * duplicate, household and customer-code rules.
433	     *
434	     * @param owner the newly mapped owner to canonicalize
435	     */
436	    private void normalizeOwnerFields(Owner owner) {
437	        // Canonicalize the owner's address fields on create so the address is stored and returned in
438	        // canonical form and every later comparison (household duplicate detection and the shared
439	        // household id) uses it. A value that is blank after normalization is rejected with 400.
440	        normalizeAddressFields(owner);
441	        // Normalize the telephone on create so it is stored and returned in canonical E.164 form.
442	        // A value that cannot form a valid E.164 number, or whose national-number length is wrong
443	        // for its country code (+61 => 9 national digits, +1 => 10), is rejected with 400.
444	        owner.setTelephone(telephoneNormalizer.normalizeAndValidate(owner.getTelephone()));
445	        // Store the (already syntactically validated) email lower-cased so it is persisted and
446	        // returned in canonical form. A missing email is left untouched.
447	        owner.setEmail(emailNormalizer.normalize(owner.getEmail()));
448	        // Reject an email whose domain is on the disposable-domain blocklist with 400, after
449	        // canonicalization so the comparison sees the lower-cased value.
450	        rejectDisposableEmailDomain(owner.getEmail());
451	        // Validate the optional postcode against the fixed range for the city's region. A postcode
452	        // is checked only when present (it is optional); one out of range for the city's region is
453	        // rejected with 400. A city with no known region accepts any 4-digit postcode. The stored
454	        // value is left unchanged.
455	        PostcodeValidator.validate(owner.getCity(), owner.getPostcode());
456	        // Reject a supplied registration date that is later than the server's current date with
457	        // 400, before any defaulting or business-day adjustment, so a future date is never
458	        // persisted regardless of how the roll-forward would move it.
459	        rejectFutureRegistrationDate(owner.getRegistrationDate());
460	        // Default the registration date to the server's current date when the client did not
461	        // supply one, then roll the effective date forward to a business day so a Saturday or
462	        // Sunday (whether supplied or defaulted) becomes the following Monday. The adjusted date
463	        // is persisted and returned in ISO 'YYYY-MM-DD' form and is the value every registration-
464	        // date-derived field (such as the membership number's year segment) and the per-day
465	        // create-limit are computed from.
466	        java.time.LocalDate effectiveDate = owner.getRegistrationDate() == null
467	            ? java.time.LocalDate.now() : owner.getRegistrationDate();
468	        owner.setRegistrationDate(toBusinessDay(effectiveDate));
469	    }
470	
471	    /**
472	     * Canonicalizes a newly mapped owner's address on create, in place, so it is persisted and
473	     * returned in canonical form. The owner may supply its address in either of two forms and the
474	     * structured form is preferred when present: when a non-blank {@code addressLine1} is supplied it
475	     * (and the optional {@code addressLine2}) is normalized (trimmed, whitespace collapsed, upper-cased
476	     * and common street-type abbreviations expanded) via {@link AddressNormalizer}, otherwise the flat
477	     * {@code address} input is normalized for backward compatibility. Whichever form is supplied, the
478	     * stored {@code address} is composed from the normalized structured lines when present — the
479	     * normalized {@code addressLine1} with a single space and the normalized {@code addressLine2}
480	     * appended when an {@code addressLine2} is present — or the normalized flat address otherwise. An
481	     * owner that supplies no address in either form is rejected with 400. Canonicalising the address
482	     * here, before the household checks read it, ensures duplicate detection and the shared household
483	     * id both compare the normalized form. Isolating the address concern in its own helper keeps
484	     * {@link #normalizeOwnerFields} focused on sequencing the per-field canonicalizations.
485	     *
486	     * @param owner the newly mapped owner whose address is canonicalized
487	     */
488	    private void normalizeAddressFields(Owner owner) {
489	        if (owner.getAddressLine1() != null && !owner.getAddressLine1().isBlank()) {
490	            String line1 = addressNormalizer.normalize(owner.getAddressLine1());
491	            owner.setAddressLine1(line1);
492	            String composed = line1;
493	            if (owner.getAddressLine2() != null && !owner.getAddressLine2().isBlank()) {
494	                String line2 = addressNormalizer.normalize(owner.getAddressLine2());
495	                owner.setAddressLine2(line2);
496	                composed = line1 + " " + line2;
497	            }
498	            owner.setAddress(composed);
499	        }
500	        else {
501	            owner.setAddress(addressNormalizer.normalize(owner.getAddress()));
502	        }
503	    }
