505	    /**
506	     * Rejects a supplied email whose domain is on the disposable-domain blocklist
507	     * ({@link #DISPOSABLE_EMAIL_DOMAINS}) with a 400 Bad Request. The email is already canonicalized
508	     * (lower-cased) here, so the domain — the part after the final {@code '@'} — is compared directly
509	     * against the lower-cased blocklist. A {@code null} email (email is optional) or one without a
510	     * domain part is left untouched.
511	     *
512	     * @param email the owner's canonicalized email, or {@code null} when absent
513	     */
514	    private void rejectDisposableEmailDomain(String email) {
515	        if (email == null) {
516	            return;
517	        }
518	        int at = email.lastIndexOf('@');
519	        if (at < 0) {
520	            return;
521	        }
522	        String domain = email.substring(at + 1).toLowerCase(Locale.ROOT);
523	        if (DISPOSABLE_EMAIL_DOMAINS.contains(domain)) {
524	            throw new DisposableEmailException(
525	                "The supplied email domain " + domain + " is on the disposable-domain blocklist");
526	        }
527	    }
