529	    /**
530	     * Rejects a supplied registration date that is later than the server's current date with a
531	     * 400 Bad Request. A missing registration date (defaulted to the server date later) is
532	     * accepted, and a date on or before today is left for the normal defaulting and business-day
533	     * adjustment.
534	     *
535	     * @param registrationDate the client-supplied registration date, or {@code null} when absent
536	     */
537	    private void rejectFutureRegistrationDate(java.time.LocalDate registrationDate) {
538	        if (registrationDate != null && registrationDate.isAfter(java.time.LocalDate.now())) {
539	            throw new InvalidRegistrationDateException(
540	                "The supplied registration date " + registrationDate + " is later than the current date");
541	        }
542	    }
