544	    /**
545	     * The fixed list of public holidays. A registration date that lands on one of these dates is
546	     * rolled forward to the next non-holiday business day, in addition to the weekend rule.
547	     */
548	    private static final java.util.Set<java.time.LocalDate> PUBLIC_HOLIDAYS = java.util.Set.of(
549	        java.time.LocalDate.of(2026, 1, 1),
550	        java.time.LocalDate.of(2026, 1, 26),
551	        java.time.LocalDate.of(2026, 4, 25),
552	        java.time.LocalDate.of(2026, 12, 25),
553	        java.time.LocalDate.of(2026, 12, 28));
554	
555	    /**
556	     * Rolls a registration date forward to a business day: a Saturday, Sunday or listed public
557	     * holiday advances to the next non-holiday weekday, while an ordinary weekday is returned
558	     * unchanged. Applied to the effective registration date (whether supplied in the request or
559	     * defaulted to the server date) so the persisted registration date, every value derived from it
560	     * and the per-day create-limit all use the adjusted business day.
561	     *
562	     * @param date the effective registration date
563	     * @return the same date if it is a non-holiday weekday, otherwise the next non-holiday business day
564	     */
565	    private java.time.LocalDate toBusinessDay(java.time.LocalDate date) {
566	        java.time.LocalDate adjusted = date;
567	        while (adjusted.getDayOfWeek() == java.time.DayOfWeek.SATURDAY
568	            || adjusted.getDayOfWeek() == java.time.DayOfWeek.SUNDAY
569	            || PUBLIC_HOLIDAYS.contains(adjusted)) {
570	            adjusted = adjusted.plusDays(1);
571	        }
572	        return adjusted;
573	    }
