575	    /**
576	     * Builds the customer code '<REGION>-<HASH8>' for a newly created owner, where REGION is the
577	     * region derived from the owner's postcode (falling back to the city, via
578	     * {@link LocalityResolver}) and HASH8 is the first 8 upper-case hex characters of the SHA-256
579	     * digest over the owner's normalized telephone concatenated with the last name (e.g.
580	     * 'NSW-A1B2C3D4'). When that base code already belongs to an existing owner, '-<n>' is appended
581	     * with the smallest n of 2 or more that makes it unique, so distinct owners always receive
582	     * distinct customer codes.
583	     *
584	     * @param owner the owner being created, already normalized
585	     * @return the formatted, de-duplicated customer code
586	     */
587	    private String customerCode(Owner owner) {
588	        String region = LocalityResolver.resolve(owner.getCity(), owner.getPostcode());
589	        String hash8 = Sha256Hex.upperHexPrefix(owner.getTelephone() + owner.getLastName(), 8);
590	        String base = region + "-" + hash8;
591	        Set<String> taken = existingOwners()
592	            .map(Owner::getCustomerCode)
593	            .filter(code -> code != null)
594	            .collect(Collectors.toSet());
595	        if (!taken.contains(base)) {
596	            return base;
597	        }
598	        int n = 2;
599	        while (taken.contains(base + "-" + n)) {
600	            n++;
601	        }
602	        return base + "-" + n;
603	    }
