605	    /**
606	     * Streams the existing owners that the create-time rules match a new owner against. Every
607	     * duplicate, quota and derived-field rule scans this same set of owners and differs only in the
608	     * predicate it applies, so fetching them is centralized here to keep each rule focused on its
609	     * own matching criterion rather than on how the existing owners are retrieved.
610	     *
611	     * @return a stream over all existing owners
612	     */
613	    private Stream<Owner> existingOwners() {
614	        // Exclude soft-deleted owners: a deleted owner is retained for reads but must not block a
615	        // new create, so the duplicate, identity and household checks (and the other create-time
616	        // scans built on this helper) ignore it.
617	        return this.clinicService.findAllOwners().stream()
618	            .filter(existing -> !Boolean.TRUE.equals(existing.getDeleted()));
619	    }
620	
621	    /**
622	     * Counts the existing owners located in the given city, compared case-insensitively. Used to
623	     * fix the per-city sequence of an owner's customer code at creation time.
624	     *
625	     * @param city the city of the owner being created
626	     * @return the number of existing owners in a matching city
627	     */
628	    private int countOwnersInCity(String city) {
629	        return (int) existingOwners()
630	            .filter(existing -> existing.getCity() != null
631	                && existing.getCity().equalsIgnoreCase(city))
632	            .count();
633	    }
634	
635	    /**
636	     * Counts the existing owners whose registration date is the given adjusted business day. Used
637	     * to enforce the per-day cap that rejects creating an owner once {@link #MAX_OWNERS_PER_DAY}
638	     * owners already carry that business day as their registration date.
639	     *
640	     * @param date the adjusted business-day registration date to match
641	     * @return the number of existing owners registered on that date
642	     */
643	    private int countOwnersRegisteredOn(java.time.LocalDate date) {
644	        return (int) existingOwners()
645	            .filter(existing -> date.equals(existing.getRegistrationDate()))
646	            .count();
647	    }
648	
649	    /**
650	     * Builds the membership number '<customerCode>-M<YY>' for a newly created owner, where YY is
651	     * the last two digits of the fiscal year of the (business-day-adjusted) registration date
652	     * (e.g. 'NSW-A1B2C3D4-M26'). The fiscal year starts on 1 July, so a registration date on or
653	     * after 1 July carries the following calendar year's fiscal year.
654	     *
655	     * @param customerCode     the owner's customer code
656	     * @param registrationDate the owner's registration date
657	     * @return the formatted membership number
658	     */
659	    private String membershipNumber(String customerCode, java.time.LocalDate registrationDate) {
660	        return String.format("%s-M%02d",
661	            customerCode, org.springframework.samples.petclinic.util.FiscalYear.of(registrationDate) % 100);
662	    }
663	
664	    /**
665	     * Returns the existing owners in the given owner's household, i.e. those sharing its
666	     * deterministic household id (the same last name and postcode). The id is computed via
667	     * {@link HouseholdNormalizer} so that last names differing only in letter case or in incidental
668	     * whitespace are treated as the same household. Centralising how "the same household" is matched
669	     * here keeps that definition in one place for every caller.
670	     *
671	     * @param owner the owner being created, with its household id already assigned
672	     * @return the existing owners in the owner's household (possibly empty)
673	     */
674	    private List<Owner> sameHouseholdOwners(Owner owner) {
675	        String householdId = owner.getHouseholdId();
676	        return existingOwners()
677	            .filter(existing -> householdId.equals(
678	                householdNormalizer.householdId(existing.getLastName(), existing.getPostcode())))
679	            .toList();
680	    }
681	
682	    /**
683	     * Counts the existing owners who share the given first and last name, compared
684	     * case-insensitively. Used to fix an owner's namesake count at creation time.
685	     *
686	     * @param firstName the first name of the owner being created
687	     * @param lastName  the last name of the owner being created
688	     * @return the number of existing owners with a matching first and last name
689	     */
690	    private int countNamesakes(String firstName, String lastName) {
691	        return (int) existingOwners()
692	            .filter(existing -> existing.getFirstName() != null
693	                && existing.getFirstName().equalsIgnoreCase(firstName)
694	                && existing.getLastName() != null
695	                && existing.getLastName().equalsIgnoreCase(lastName))
696	            .count();
697	    }
