710	        // Normalize the telephone to canonical E.164 form so it is stored and returned
711	        // consistently with create; an unformattable value is rejected with 400.
712	        currentOwner.setTelephone(telephoneNormalizer.normalize(ownerFieldsDto.getTelephone()));
713	        currentOwner.setEmail(emailNormalizer.normalize(ownerFieldsDto.getEmail()));
714	        this.clinicService.saveOwner(currentOwner);
