17	package org.springframework.samples.petclinic.util;
18	
19	import java.util.Locale;
20	import java.util.Map;
21	
22	import org.springframework.samples.petclinic.rest.advice.InvalidAddressException;
23	import org.springframework.stereotype.Component;
24	
25	/**
26	 * Produces the canonical stored form of an owner's postal address.
27	 * <p>
28	 * Centralising this here keeps the REST controllers thin: they delegate to
29	 * {@link #normalize(String)} when canonicalising an incoming value before it is persisted,
30	 * and because addresses are stored in canonical form every later comparison of addresses
31	 * (household duplicate detection and the shared household id) operates on the same form and
32	 * they therefore always agree.
33	 * <p>
34	 * The canonical form trims the value, collapses runs of whitespace to a single space and
35	 * upper-cases it, then expands common street-type abbreviations token-by-token
36	 * ({@code ST -> STREET}, {@code RD -> ROAD}, {@code AVE -> AVENUE}). A value that is blank
37	 * after normalization carries no address and is rejected with {@link InvalidAddressException}
38	 * (a 400), so the required-field check is applied to the normalized value rather than the raw
39	 * input.
40	 */
41	@Component
42	public class AddressNormalizer {
43	
44	    private static final Map<String, String> ABBREVIATIONS = Map.of(
45	        "ST", "STREET",
46	        "RD", "ROAD",
47	        "AVE", "AVENUE");
48	
49	    /**
50	     * Normalizes the supplied address to its canonical stored form: trimmed, with internal runs
51	     * of whitespace collapsed to a single space, upper-cased and with common street-type
52	     * abbreviations expanded ({@code ST -> STREET}, {@code RD -> ROAD}, {@code AVE -> AVENUE}).
53	     * Values that differ only in letter case, incidental whitespace or the use of these
54	     * abbreviations therefore normalize to the same result.
55	     *
56	     * @param address the raw address value (may be {@code null})
57	     * @return the normalized address
58	     * @throws InvalidAddressException if the value is blank after normalization
59	     */
60	    public String normalize(String address) {
61	        String collapsed = address == null ? "" : address.trim().replaceAll("\\s+", " ");
62	        if (collapsed.isEmpty()) {
63	            throw new InvalidAddressException("Address must not be blank after normalization");
64	        }
65	        String[] tokens = collapsed.toUpperCase(Locale.ROOT).split(" ");
66	        StringBuilder sb = new StringBuilder(collapsed.length());
67	        for (int i = 0; i < tokens.length; i++) {
68	            if (i > 0) {
69	                sb.append(' ');
70	            }
71	            sb.append(ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
72	        }
73	        return sb.toString();
74	    }
75	}
